// 1. EXTRACT DATA
// The 'items' variable is automatically available in n8n JS nodes.
// We map the incoming SQL rows into a clean array.
const historicalData = items.map(item => item.json);

// 2. DEFINE SIMULATION PARAMETERS
// Since the SQL node only provides history, we define projection settings here.
// You can change these numbers to adjust your scenario.
const params = {
  projection_horizon: 12,    // Project 12 months ahead
  revenue_growth_rate: 5,    // 5% monthly growth
  dso_change: 0,             // Change in Days Sales Outstanding
  dio_change: 0,             // Change in Days Inventory Outstanding
  dpo_change: 0,             // Change in Days Payable Outstanding
  opex_change_rate: 2,       // 2% monthly increase in OpEx
  scenario_id: 'scenario_001'
};

// 3. GET BASELINE (Latest Month)
if (historicalData.length === 0) {
  return [{json: {error: "No historical data found"}}];
}

// Get the last row from the SQL results
const baseline = historicalData[historicalData.length - 1];

// Helper function to safely convert SQL strings/nulls to numbers
const safeFloat = (val) => val ? parseFloat(val) : 0;

// Extract baseline values safely
const baselineRevenue = safeFloat(baseline.revenue);
const baselineReceivables = safeFloat(baseline.trade_receivables_total);
const baselineInventory = safeFloat(baseline.inventory);
const baselinePayables = safeFloat(baseline.accounts_payable_total);
const baselineCash = safeFloat(baseline.cash_total_egp_eq);
const baselineCurrentAssets = safeFloat(baseline.current_assets);
const baselineCurrentLiabilities = safeFloat(baseline.total_liabilities); // Using Total Liab as proxy if Current is missing
const baselineOpex = safeFloat(baseline.operating_expenses);
const baselineCogs = safeFloat(baseline.cogs);
const baselineShortTermDebt = safeFloat(baseline.short_term_debt);
const baselineTotalDebt = safeFloat(baseline.total_debt);

// Calculate Baseline Ratios
const baselineDso = baselineRevenue ? (baselineReceivables / baselineRevenue) * 30 : 0;
const baselineDio = baselineCogs ? (baselineInventory / baselineCogs) * 30 : 0;
const baselineDpo = baselineCogs ? (baselinePayables / baselineCogs) * 30 : 0;

const results = [];

// 4. PROJECTION LOOP
for (let month = 1; month <= params.projection_horizon; month++) {

    // Apply Revenue Growth
    const projectedRevenue = baselineRevenue * Math.pow((1 + params.revenue_growth_rate / 100), month);

    // Projected Working Capital
    const projectedDso = baselineDso + params.dso_change;
    const projectedReceivables = (projectedRevenue / 30) * projectedDso;

    const projectedDio = baselineDio + params.dio_change;
    const projectedCogs = baselineRevenue ? projectedRevenue * (baselineCogs / baselineRevenue) : 0;
    const projectedInventory = (projectedCogs / 30) * projectedDio;

    const projectedDpo = baselineDpo + params.dpo_change;
    const projectedPayables = (projectedCogs / 30) * projectedDpo;

    // Cash Conversion Cycle
    const ccc = projectedDso + projectedDio - projectedDpo;

    // Operating Expenses
    const projectedOpex = baselineOpex * Math.pow((1 + params.opex_change_rate / 100), month);

    // Monthly Burn Rate
    // (Money Out - Money In)
    const collections = projectedRevenue / (1 + projectedDso / 30);
    const payments = projectedCogs + projectedOpex;
    const monthlyBurn = payments - collections;

    // Projected Cash Position
    const projectedCash = baselineCash - (monthlyBurn * month);

    // Runway (Months until cash runs out)
    let runway = 999;
    if (monthlyBurn > 0) {
        runway = projectedCash / monthlyBurn;
    }

    // Current Ratio
    const projectedCurrentAssets = projectedCash + projectedReceivables + projectedInventory;
    const projectedCurrentLiabilities = projectedPayables + baselineShortTermDebt;
    const currentRatio = projectedCurrentLiabilities > 0 ? projectedCurrentAssets / projectedCurrentLiabilities : 0;

    // Defensive Interval Ratio
    const defensiveAssets = projectedCash + projectedReceivables;
    const defensiveInterval = projectedOpex > 0 ? (defensiveAssets / projectedOpex) * 30 : 0;

    // Working Capital Turnover
    const workingCapital = projectedCurrentAssets - projectedCurrentLiabilities;
    const wcTurnover = workingCapital > 0 ? projectedRevenue / workingCapital : 0;

    // CF to Debt Ratio
    const operatingCf = projectedRevenue - projectedCogs - projectedOpex;
    const cfToDebt = baselineTotalDebt > 0 ? operatingCf / baselineTotalDebt : 0;

    // Push Result Object
    results.push({
        scenario_id: params.scenario_id,
        agent_type: 'liquidity',
        month: month,
        metrics: {
            cash_conversion_cycle: Number(ccc.toFixed(2)),
            burn_rate: Number(monthlyBurn.toFixed(2)),
            runway: Number(runway.toFixed(2)),
            current_ratio: Number(currentRatio.toFixed(2)),
            defensive_interval: Number(defensiveInterval.toFixed(2)),
            cf_to_debt_ratio: Number(cfToDebt.toFixed(4)),
            wc_turnover: Number(wcTurnover.toFixed(2))
        },
        projected_values: {
            cash: Number(projectedCash.toFixed(2)),
            receivables: Number(projectedReceivables.toFixed(2)),
            inventory: Number(projectedInventory.toFixed(2)),
            current_assets: Number(projectedCurrentAssets.toFixed(2)),
            current_liabilities: Number(projectedCurrentLiabilities.toFixed(2))
        }
    });
}

// Return the results wrapped in the structure n8n expects
return [{json: {results: results}}];
